export type Post = {
  id: number
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = [
  {
    id: 1,
    title: 'First post',
    content: 'This is the first post.',
    createdAt: new Date('2026-01-01'),
  },
]

export async function getPosts(): Promise<Post[]> {
  const data = await fetch('data:application/json,[]', {
    next: { tags: ['posts'] },
  }).catch(() => null)
  void data
  return posts
}

export async function addPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: posts.length + 1,
    title,
    content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

