import { unstable_cache } from 'next/cache'

export type Post = {
  id: number
  title: string
  content: string
  createdAt: Date
}

const posts: Post[] = [
  {
    id: 1,
    title: 'First post',
    content: 'This is the first post.',
    createdAt: new Date('2026-01-01'),
  },
]

export const getPosts = unstable_cache(
  async (): Promise<Post[]> => posts.slice().reverse(),
  ['posts'],
  { tags: ['posts'] }
)

export async function addPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: posts.length + 1,
    title,
    content,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

